import fs from 'fs/promises';
import path from 'path';

type PathContainment = {
  isPathWithinRoot: (root: string, candidate: string) => boolean;
  isPathStrictlyInsideRoot: (root: string, candidate: string) => boolean;
  isConfinedRelativePath: (relativePath: string) => boolean;
};

const PATH_SEPARATORS = /[\\/]+/;

export const createPathContainment = (
  platformPath: typeof path,
): PathContainment => {
  const isOutsideRoot = (relativePath: string): boolean =>
    relativePath === '..' ||
    relativePath.startsWith(`..${platformPath.sep}`) ||
    platformPath.isAbsolute(relativePath);
  return {
    isPathWithinRoot: (root, candidate) =>
      !isOutsideRoot(platformPath.relative(root, candidate)),
    isPathStrictlyInsideRoot: (root, candidate) => {
      const relativePath = platformPath.relative(root, candidate);
      return relativePath !== '' && !isOutsideRoot(relativePath);
    },
    isConfinedRelativePath: (relativePath) =>
      !relativePath.includes('\0') &&
      !platformPath.isAbsolute(relativePath) &&
      !relativePath.split(PATH_SEPARATORS).includes('..'),
  };
};

export const {
  isPathWithinRoot,
  isPathStrictlyInsideRoot,
  isConfinedRelativePath,
} = createPathContainment(path);

export const resolveRealPathWithinRoot = async ({
  root,
  candidate,
  containment,
}: {
  root: string;
  candidate: string;
  containment: 'inclusive' | 'strict';
}): Promise<string | null> => {
  let realRoot: string;
  let realCandidate: string;
  try {
    [realRoot, realCandidate] = await Promise.all([
      fs.realpath(root),
      fs.realpath(candidate),
    ]);
  } catch {
    return null;
  }
  const isContained =
    containment === 'strict'
      ? isPathStrictlyInsideRoot(realRoot, realCandidate)
      : isPathWithinRoot(realRoot, realCandidate);
  return isContained ? realCandidate : null;
};
